376	24	2	indParent ( TreeNode<Type> *t,\nTreeNode<Type> *p) {\n//在根为 t 的树中找 p 的双亲 ,使之成为当前结点\nTreeNode <Type> *q=t→firstChild;\nwhile ( q!= NULL && q != p ) {\n//循根的长子的兄弟链,递归在子树中搜索\nif((inti= FindParent (*q,*p)) != 0 ) return i;\nq= q→nextSibling ;\n}\nif( q!= NULL && q ==p )\n{current = t; return 1;}\nelse return 0;       //未找到双亲,当前结点不变\n}\ntemplate <class Type> int Tree<Type> ::\nFind ( Type target ) {\nif(IsEmpty ( ) ) return 0;\nreturn Find ( root, target );\n}template <class Type> int Tree <Type>::\nFind ( TreeNode <T	61	{"resource_name": "ds06_tree.pdf", "file_type": "pdf", "object_name": "courses/2/ddd580bb4fac40599434523c852c0d94_ds06_tree.pdf"}	[-0.080011256,0.044028964,-0.0594391,0.037386663,-0.08502145,-0.010807972,0.046799753,0.085401006,-0.014812331,0.009090463,-0.02431082,-0.00013595959,-0.05070922,0.007752514,-0.0019061031,-0.005925881,0.0071641956,0.027480148,0.040992483,-0.053669788,-0.06991496,0.014091167,0.012848107,0.04550925,-0.005584277,0.016937867,-0.015372181,-0.066233225,-0.042776417,-0.043345757,0.04243481,-0.052758846,0.041182265,-0.0866156,-0.024386732,-0.042700503,0.0047919457,-0.014603573,-0.06482886,-0.020002814,-0.014356858,-0.03590638,0.02746117,0.006229529,0.027499124,-0.047027487,0.0028395834,-0.067371905,0.0018966141,0.015884588,-0.04558516,-0.0048868353,-0.009522213,-0.024671402,-0.030535605,0.0053802636,-0.017336404,-0.030725386,-0.04380123,-0.01395832,-0.03894286,0.027024675,-0.033610042,0.063766085,-0.015172913,0.017118158,-0.012117454,-0.04714136,-0.013815985,-0.02582906,-0.024652425,0.022071416,-0.043915097,-0.0129335085,-0.004066037,0.01966121,0.016359037,0.0030744362,-0.06220989,-0.032148734,0.09633234,-0.021577988,-0.008900683,-0.0006150059,0.0036912214,0.013550294,0.032433406,0.02042033,0.00096906425,0.0039308188,-0.04406692,-0.06961131,-0.04600268,0.022394042,-0.031332683,-0.049722366,-0.0054941317,0.040385187,0.07864484,0.011519647,0.031180857,0.06213398,-0.028599849,-0.055719413,0.0103525,-0.03342026,-0.0015301014,0.00