455	25	2	( Binary Search Tree )\n二叉搜索树的类定义\n#include <iostream.h >\ntemplate <class Type> class BST;\n如果对一棵二叉搜索树进行中序遍历，可以按\n从小到大的顺序，将各结点关键码排列起来，所\n以也称二叉搜索树为二叉排序树。几个二叉搜索树的例子\ntemplate <class Type> Class BstNode <Type >:\npublic BinTreeNode {   //\n二叉搜索树结点类\nfriend class BST <Type >;\npublic:\nBstNode ( ) :\nleftChild (NULL ), rightChild (NULL ) {}\nBstNode (const Type d):data (d),\nleftChild (NULL ), rightChild (NULL ) { }\nBstNode ( const Type d = 0, BstNode *L = NULL ,\nBstNode *R= NULL ) : data (d), leftChild (L),\nri	49	{"resource_name": "ds07_set_and_search.pdf", "file_type": "pdf", "object_name": "courses/2/28bcf0025068421aa75e68ecd11868e2_ds07_set_and_search.pdf"}	[-0.10472688,-0.019554771,-0.07837253,0.029902784,-0.04699283,0.002216575,0.0395507,0.07599412,-0.019832892,0.044038996,-0.03962742,-0.0030641244,0.046072155,0.038073782,0.027083214,-0.03208939,-0.005826152,-0.042504534,0.017770963,-0.055432357,-0.0600741,0.0063823937,0.0054089706,0.04085499,-0.005643935,0.028349144,-0.022825088,-0.03343204,-0.018576553,-0.03935889,0.03230038,0.012774377,0.074574746,-0.049985025,-0.029078012,-0.011565991,0.01795318,-0.029979507,-0.040778268,0.04331013,-0.0060994774,0.04848893,0.042197645,-0.04983158,0.017761372,-9.389013e-06,0.013177173,-0.06494601,-0.042581256,0.0096766865,-0.055547442,-0.024723982,0.0012227726,-0.010348013,-0.004310873,-0.034582887,-0.0400494,0.004121463,-0.094983056,-0.021961955,-0.06720934,0.024628079,0.0046489337,0.05497202,0.0036635227,0.007211961,-0.0029682205,-0.019986339,0.004663319,-0.012131822,-0.0048455363,0.01977535,-0.07116057,-0.007422949,-0.025625478,0.03159069,-0.001047149,-0.00455303,-0.085929744,-0.0060035735,0.07587904,-0.039435614,-0.0055624167,0.0038745108,-0.018375155,0.07522689,0.043732103,0.049256157,0.002800389,-0.042312726,-0.011537219,-0.03669277,-0.031245437,-0.0034717151,-0.027716178,-0.04342521,0.025644658,-0.008041528,0.02539531,0.012649703,-0.018634096,0.03746,-0.009547217,-0.020638485,-0.015239104,-0.04526656,0.03488